// Clean-room TSVC s1213 profile; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s1213_ordered_neighbor_array_map(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<13||length>129{return -1;}let v=core::slice::from_raw_parts(input,length);let nr=v[0];if !(3..=32).contains(&nr){return -1;}let n=nr as usize;if length!=1+4*n{return -1;}let mut a=[0i64;32];let mut b=[0i64;32];let mut c=[0i64;32];let mut d=[0i64;32];for i in 0..n{let x=v[1+i];let y=v[1+n+i];let z=v[1+2*n+i];let w=v[1+3*n+i];if !(-1..=1).contains(&x)||!(-1..=1).contains(&y)||!(-1..=1).contains(&z)||!(-1..=1).contains(&w){return -1;}a[i]=x;b[i]=y;c[i]=z;d[i]=w;}if output.is_null()||capacity<16*n{return -2;}for i in 1..n-1{a[i]=b[i-1]+c[i];b[i]=a[i+1]*d[i];}for i in 0..n{for (k,val) in [a[i],b[i]].iter().enumerate(){let bits=*val as u64;let base=8*(k*n+i);for j in 0..8{output.add(base+j).write((bits>>(8*j))as u8);}}}n as i64*2}
